const produto = {
  nome: "Teclado mecânico",
  preco: 79.9,
  emStock: true,
};

console.log(produto.nome); // "Teclado mecânico" — notação de ponto

const campo = "preco";
console.log(produto[campo]); // 79.9 — notação de colchetes, chave dinâmica

produto.desconto = 0.1; // adicionar propriedade nova
delete produto.emStock; // remover propriedade existente

function criarUtilizador(nome, idade) {
  const ativo = true;
  return { nome, idade, ativo }; // shorthand de propriedades
}

const utilizador = criarUtilizador("Marta", 32);

const carrinho = {
  itens: [],
  adicionar(item) {           // shorthand de método
    this.itens.push(item);
    return this.itens.length;
  },
};

carrinho.adicionar("Livro");

const idioma = "pt";

const traducoes = {
  [`titulo_${idioma}`]: "Bem-vindo",
  [idioma === "pt" ? "saudacao" : "greeting"]: "Olá!",
};

console.log(traducoes.titulo_pt); // "Bem-vindo"

function criarRegisto(chave, valor) {
  return { [chave]: valor };
}

console.log(criarRegisto("email", "marta@example.com"));
// { email: "marta@example.com" }

const stock = { maçã: 50, banana: 12, pera: 0 };

console.log(Object.keys(stock));   // ["maçã", "banana", "pera"]
console.log(Object.values(stock)); // [50, 12, 0]
console.log(Object.entries(stock));
// [["maçã", 50], ["banana", 12], ["pera", 0]]

for (const [fruta, quantidade] of Object.entries(stock)) {
  console.log(`${fruta}: ${quantidade} unidades`);
}

const disponiveis = Object.entries(stock).filter(([, qtd]) => qtd > 0);
// [["maçã", 50], ["banana", 12]]

const stock = { maçã: 50, banana: 12, pera: 0 };

// filtrar propriedades e devolver um objeto (não um array)
const comStock = Object.fromEntries(
  Object.entries(stock).filter(([, quantidade]) => quantidade > 0)
);
console.log(comStock); // { "maçã": 50, banana: 12 }

// converter um Map num objeto
const configuracoes = new Map([
  ["tema", "escuro"],
  ["idioma", "pt-PT"],
]);
console.log(Object.fromEntries(configuracoes));
// { tema: "escuro", idioma: "pt-PT" }

const utilizador = {
  nome: "Rui",
  morada: {
    cidade: "Porto",
  },
};

console.log(utilizador.morada?.rua);      // undefined, sem erro
console.log(utilizador?.contacto?.email); // undefined, sem erro

console.log(utilizador.morada?.["cidade"]); // "Porto" — também com colchetes

utilizador.saudar?.(); // não faz nada, "saudar" não existe — não lança erro

