function criarLivro(titulo, autor, paginas) {
  return { titulo, autor, paginas, lido: false };
}

const livro = criarLivro("Duna", "Frank Herbert", 688);
console.log(livro.titulo);     // "Duna"
console.log(livro["paginas"]); // 688

function construirObjeto(respostas) {
  return respostas.reduce((acc, { campo, valor }) => {
    return { ...acc, [campo]: valor };
  }, {});
}

const respostas = [
  { campo: "nome", valor: "Ana" },
  { campo: "idade", valor: 25 },
];

console.log(construirObjeto(respostas)); // { nome: "Ana", idade: 25 }

function aplicarDesconto(precos, percentagem) {
  const fator = 1 - percentagem / 100;
  return Object.fromEntries(
    Object.entries(precos).map(([produto, preco]) => [
      produto,
      Number((preco * fator).toFixed(2)),
    ])
  );
}

const precos = { teclado: 79.9, rato: 39.9, monitor: 249.9 };
console.log(aplicarDesconto(precos, 10));
// { teclado: 71.91, rato: 35.91, monitor: 224.91 }
console.log(precos); // objeto original inalterado

function listarCidades(pedidos) {
  return Object.fromEntries(
    pedidos.map((pedido) => [
      pedido.id,
      pedido.cliente?.morada?.cidade ?? "desconhecida",
    ])
  );
}

const pedidos = [
  { id: 1, cliente: { nome: "Sofia", morada: { cidade: "Lisboa" } } },
  { id: 2, cliente: { nome: "Tiago" } },
  { id: 3 },
];

console.log(listarCidades(pedidos));
// { "1": "Lisboa", "2": "desconhecida", "3": "desconhecida" }
